+type Binding struct {
+ Version int `json:"version"`
+ Provider string `json:"provider"`
+ Workspace string `json:"workspace"`
+ WorkspaceName string `json:"workspace_name,omitempty"`
+ Projects []string `json:"projects"`
+}
+type Completeness struct {
+ Missing []string `json:"missing,omitempty"`
+ Truncated []string `json:"truncated,omitempty"`
+ Limitations []string `json:"limitations,omitempty"`
+}
+type Record struct {
+ Kind string `json:"kind"`
+ Workspace string `json:"workspace"`
+ ID string `json:"id"`
+ Project string `json:"project"`
+ Issue string `json:"issue,omitempty"`
+ Alias string `json:"alias,omitempty"`
+ URL string `json:"url"`
+ Title string `json:"title,omitempty"`
+ Text string `json:"text"`
+ Fields map[string]json.RawMessage `json:"fields,omitempty"`
+ UpdatedAt time.Time `json:"updated_at"`
+ ObservedAt time.Time `json:"observed_at"`
+ Completeness Completeness `json:"completeness"`
+ // Only an explicit remote observation may set deleted or inaccessible.
+ Availability string `json:"availability,omitempty"`
+}
+func (r Record) Key() string { return "issue:"+r.Workspace+":"+r.Kind+":"+r.ID }
+func (r Record) Group() string { if r.Kind == "comment" { return r.Workspace+":"+r.Issue }; return r.Workspace+":"+r.ID }
+func Hash(data []byte) string { h:=sha256.Sum256(data); return hex.EncodeToString(h[:]) }
+func (r Record) ContentHash() string { r.ObservedAt=time.Time{}; b,_:=json.Marshal(r); return Hash(b) }
+type Snapshot struct {
+ Record
+ Hash string `json:"content_hash"`
+ Ref string `json:"snapshot"`
+}
+type Page struct {
+ Complete bool `json:"complete"`
+ Cursor string `json:"cursor,omitempty"`
+}
+type Progress struct {
+ Project string `json:"project"`
+ WindowStart time.Time `json:"window_start"`
+ Issues Page `json:"issues"`
+ Comments map[string]Page `json:"comments"`
+ Complete bool `json:"complete"`
+ Limitations []string `json:"limitations,omitempty"`
+}
+type Envelope struct {
+ Version int `json:"version"`
+ Workspace string `json:"workspace"`
+ RunID string `json:"run_id"`
+ BatchID string `json:"batch_id"`
+ Records []Record `json:"records"`
