+}
+type State struct {
+ Binding Binding `json:"binding"`
+ Current map[string]string `json:"current"`
+ Snapshots map[string]Record `json:"snapshots"`
+ Batches map[string]string `json:"batches"`
+ Runs map[string]Progress `json:"runs"`
+ Links []Link `json:"links,omitempty"`
+ Operations map[string][]Operation `json:"operations"`
+}
+// The adapter supplies Brain's cross-process lock and platform-specific atomic
+// writer. All durable state is published by one replacement while holding it.
+type Store struct {
+ Root string
+ Lock func(func() error) error
+ Write func(string, []byte) error
+}
+func (s Store) Load() (State,error) {
+ st:=State{Current:map[string]string{},Snapshots:map[string]Record{},Batches:map[string]string{},Runs:map[string]Progress{},Operations:map[string][]Operation{}}
+ b,err:=os.ReadFile(filepath.Join(s.Root,"state.json")); if os.IsNotExist(err) { return st,nil }; if err!=nil { return st,err }
+ err=json.Unmarshal(b,&st); if err==nil && (st.Current==nil || st.Snapshots==nil || st.Batches==nil || st.Runs==nil || st.Operations==nil || st.Binding.Version!=1) { err=errors.New("invalid issue state") }; return st,err
+}
+func (s Store) mutate(fn func(*State) error) error {
+ if s.Lock==nil || s.Write==nil { return errors.New("issue mutations require lock and atomic writer") }
+ return s.Lock(func()error { st,err:=s.Load(); if err!=nil{return err}; if err=fn(&st);err!=nil{return err}; b,err:=json.Marshal(st); if err!=nil{return err}; return s.Write(filepath.Join(s.Root,"state.json"),b) })
+}
+func Decode(data []byte, out any) error {
+ if len(data)>MaxBatchBytes {return errors.New("issue input exceeds 2 MiB")}; d:=json.NewDecoder(bytes.NewReader(data)); d.DisallowUnknownFields(); if err:=d.Decode(out);err!=nil{return err}; var extra any; if err:=d.Decode(&extra);err!=io.EOF{return errors.New("expected exactly one JSON value")};return nil
+}
+func selected(st *State, p string) bool { for _,v:=range st.Binding.Projects {if v==p{return true}};return false }
