+ return s.mutate(func(st *State)error {if st.Binding.Workspace!="" && (st.Binding.Workspace!=b.Workspace || st.Binding.Provider!=b.Provider){return errors.New("repository already bound to another workspace/provider")};st.Binding=b;return nil})
+}
+func validRecord(r Record) error {
+ if !uuid.MatchString(r.ID)||!uuid.MatchString(r.Workspace)||!uuid.MatchString(r.Project){return errors.New("record identities must be UUIDs")}
