+ if r.UpdatedAt.IsZero()||r.ObservedAt.IsZero(){return errors.New("record timestamps required")}
+ u,err:=url.Parse(r.URL);if err!=nil||u.Scheme!="https"||u.Host==""{return errors.New("canonical HTTPS URL required")}
