+}
+type ImportResult struct { Imported int `json:"imported"`; Ignored int `json:"ignored"`; Conflicts []string `json:"conflicts,omitempty"`; Replay bool `json:"replay"` }
+func (s Store) Import(data []byte) (res ImportResult, err error) {
+ var e Envelope;if err=Decode(data,&e);err!=nil{return};if e.Version!=1||!uuid.MatchString(e.Workspace)||!uuid.MatchString(e.RunID)||!uuid.MatchString(e.BatchID)||len(e.Records)>MaxRecords{return res,errors.New("invalid import version, UUIDs, or more than 100 records")}
