+ if st.Binding.Workspace!=e.Workspace{return errors.New("workspace mismatch")};batch:=e.RunID+":"+e.BatchID;digest:=Hash(data);if prior,ok:=st.Batches[batch];ok{if prior!=digest{return errors.New("batch ID reused with different payload")};res.Replay=true;return nil}
+ for _,r:=range e.Records {if err:=validRecord(r);err!=nil{return err};if r.Workspace!=e.Workspace{return errors.New("record workspace mismatch")};if !selected(st,r.Project){
+ // A previously imported issue may explicitly move outside scope. Keep that
+ // observation so both the old issue and its comments disappear immediately.
+ old,ok:=st.Snapshots[st.Current[r.Key()]];if r.Kind!="issue"||!ok||old.Project==r.Project{return errors.New("project is not selected")}
+ }}
+ for _,r:=range e.Records {
