+ if ok && old.UpdatedAt.Equal(r.UpdatedAt) && old.ContentHash()!=r.ContentHash(){res.Conflicts=append(res.Conflicts,r.Key());continue}
+ if ok && old.ContentHash()==r.ContentHash() && old.ObservedAt.After(r.ObservedAt){res.Ignored++;continue}
