+ // an earlier citation even when remote content did not change.
+ raw,_:=json.Marshal(r);ref=r.Key()+"@"+Hash(raw);st.Snapshots[ref]=r;st.Current[r.Key()]=ref;res.Imported++
+ }
+ for _,r:=range e.Records {if r.Kind=="comment"{parentKey:="issue:"+r.Workspace+":issue:"+r.Issue;p,ok:=st.Snapshots[st.Current[parentKey]];if !ok||p.Project!=r.Project{return errors.New("comment parent missing or project mismatch")}}}
+ if p:=e.Progress;p!=nil {
+ if !selected(st,p.Project)||p.WindowStart.IsZero(){return errors.New("progress requires selected project and requested window")}
