+func visible(st *State,r Record) bool {
+ if !selected(st,r.Project)||r.Availability=="deleted"||r.Availability=="inaccessible"{return false}
+ current,ok:=st.Snapshots[st.Current[r.Key()]];if !ok||!selected(st,current.Project)||current.Availability=="deleted"||current.Availability=="inaccessible"{return false}
