+func (s Store) Operation(op Operation) error {
+ if !uuid.MatchString(op.ID)||!hashPattern.MatchString(op.PayloadHash)||op.ObservedAt.IsZero(){return errors.New("operation UUID, SHA256 payload hash and observation required")}
+ switch op.Action{case "create","comment","status","assignee","priority","labels","project":default:return errors.New("unsupported operation action")}
+ switch op.Outcome{case "pending","succeeded","failed","unknown":default:return errors.New("invalid operation outcome")}
+ return s.mutate(func(st *State)error {history:=st.Operations[op.ID];if len(history)==0 {
+ if op.Outcome!="pending"{return errors.New("operation must start pending")};if op.Action=="create"{if !selected(st,op.Target){return errors.New("create target must be selected project UUID")}}else{r,ok:=st.Snapshots[st.Current[op.Target]];if !ok||r.Kind!="issue"||!visible(st,r){return errors.New("operation target must be a visible issue ID")}}
+ }else{prev:=history[len(history)-1];if prev.Target!=op.Target||prev.Action!=op.Action||prev.PayloadHash!=op.PayloadHash{return errors.New("operation intent cannot change")};a,_:=json.Marshal(prev);b,_:=json.Marshal(op);if bytes.Equal(a,b){return nil};if prev.Outcome=="succeeded"||prev.Outcome=="failed"||op.Outcome=="pending"||op.ObservedAt.Before(prev.ObservedAt){return errors.New("invalid operation transition")}}
+ if op.Outcome=="succeeded"&&(op.ObjectID==""||op.URL==""){return errors.New("success requires returned object ID and URL")};st.Operations[op.ID]=append(history,op);return nil})
+}
+func (s Store) Disconnect(project string,purge bool) error {if !uuid.MatchString(project){return errors.New("project UUID required")};return s.mutate(func(st *State)error {
+ ps:=[]string{};for _,p:=range st.Binding.Projects{if p!=project{ps=append(ps,p)}};st.Binding.Projects=ps
+ if purge {removed:=map[string]bool{};for ref,r:=range st.Snapshots{if r.Project==project{removed[r.Key()]=true;delete(st.Snapshots,ref)}};for key,ref:=range st.Current{if _,ok:=st.Snapshots[ref];!ok{delete(st.Current,key)}};links:=st.Links[:0];for _,l:=range st.Links{if !removed[l.Issue]{links=append(links,l)}};st.Links=links;for id,ops:=range st.Operations{if len(ops)>0&&(removed[ops[0].Target]||ops[0].Target==project){delete(st.Operations,id)}};for id,p:=range st.Runs{if p.Project==project{delete(st.Runs,id)}};st.Batches=map[string]string{}}
+ return nil})}
+type Status struct { Binding Binding `json:"binding"`; Records int `json:"records"`; Stale int `json:"stale"`; Incomplete int `json:"incomplete"`; Runs map[string]Progress `json:"runs,omitempty"`; Links []Link `json:"links,omitempty"`; Operations map[string][]Operation `json:"operations,omitempty"` }
+func (s Store) Status(now time.Time)(Status,error){st,err:=s.Load();if err!=nil{return Status{},err};out:=Status{Binding:st.Binding,Runs:st.Runs,Links:st.Links,Operations:st.Operations};for _,ref:=range st.Current{r:=st.Snapshots[ref];if !visible(&st,r){continue};out.Records++;if now.Sub(r.ObservedAt)>24*time.Hour{out.Stale++};if len(r.Completeness.Missing)+len(r.Completeness.Truncated)+len(r.Completeness.Limitations)>0{out.Incomplete++}};return out,nil}
