+ r:=unifiedResult{Source:"issue",ID:s.Key(),Path:s.URL,Heading:strings.TrimSpace(s.Alias+" "+s.Title),Text:text,VerificationRequired:true,Issue:&issueCitation{s.Ref,s.URL,s.ObservedAt,s.UpdatedAt,s.Hash,s.Completeness,time.Since(s.ObservedAt)>24*time.Hour}}
